static void hexfill(char out[65],char c){for(int i=0;i<64;i++)out[i]=c;out[64]=0;}
static EVP_PKEY*new_key(const char*name){EVP_PKEY_CTX*c=EVP_PKEY_CTX_new_from_name(NULL,name,NULL);EVP_PKEY*k=NULL;assert(c&&EVP_PKEY_keygen_init(c)==1&&EVP_PKEY_generate(c,&k)==1&&k);EVP_PKEY_CTX_free(c);return k;}
