static int fetch_ok(void*ctx,const QrxAiModelRecord*m,const QrxAuraModelCachePlacement*p,char out[65]){(void)m;assert(p&&p->bytes_to_place);snprintf(out,65,"%s",(const char*)ctx);return 0;}
static int worker(void*ctx,const void*in,size_t in_n,void*out,size_t cap,size_t*out_n){(void)ctx;const char*prefix="AURA:";size_t pn=strlen(prefix);if(cap<pn+in_n)return -1;memcpy(out,prefix,pn);memcpy((char*)out+pn,in,in_n);*out_n=pn+in_n;return 0;}

