    QrxAuraRuntimeBinding rb;memset(&rb,0,sizeof(rb));rb.version=QRX_AURA_LIVE_DISPATCH_VERSION;snprintf(rb.pod_id,sizeof(rb.pod_id),"pod-compute-1");snprintf(rb.provider_id,sizeof(rb.provider_id),"%s",provider);rb.provider_runtime=&rt;rb.local=1;rb.device.version=QRX_MOE_RUNTIME_VERSION;rb.device.backend=QRX_MOE_BACKEND_CPU;snprintf(rb.device.device_name,sizeof(rb.device.device_name),"generic-cpu");rb.device.accelerator_features=QRX_MOE_ACCEL_FEAT_FP32;rb.device.device_memory_bytes=8*GIB;rb.device.max_batch_items=8;rb.adapter.version=QRX_MOE_DISCOVERY_VERSION;snprintf(rb.adapter.name,sizeof(rb.adapter.name),"test-cpu-adapter");rb.adapter.backend=QRX_MOE_BACKEND_CPU;rb.adapter.kernel_mask=QRX_MOE_KERNEL_FP32;rb.adapter.ready=1;rb.adapter.execute=worker;

    QrxComputeJobGraph g;memset(&g,0,sizeof(g));g.protocol_version=QRX_COMPUTE_JOB_PROTOCOL_VERSION;snprintf(g.graph_id,sizeof(g.graph_id),"graph-aura-937");snprintf(g.owner,sizeof(g.owner),"user-1");g.nonce=1;g.max_total_fee_atoms=100000;g.expiry_height=180;g.node_count=1;QrxComputeJobNode*n=&g.nodes[0];n->node_id=1;n->job_type=QRX_JOB_AI_INFERENCE;snprintf(n->runtime_id,sizeof(n->runtime_id),"qrx-llm-runtime-v1");snprintf(n->model_id,sizeof(n->model_id),"qrx/aura-nano");snprintf(n->model_version,sizeof(n->model_version),"1");snprintf(n->input_ref,sizeof(n->input_ref),"drive:input");snprintf(n->output_ref,sizeof(n->output_ref),"drive:output");n->min_memory_bytes=2*GIB;n->max_runtime_ms=30000;n->max_output_bytes=4096;n->max_fee_atoms=100000;n->capability_mask=QRX_JOB_CAP_READ_INPUTS|QRX_JOB_CAP_STREAM_OUTPUT|QRX_JOB_CAP_MODEL_INFERENCE;assert(qrx_compute_job_graph_validate(&g)==0);
